from itertools import combinations

def max_probabilidade(n, probabilidades):
    melhor_probabilidade = 0

    for i in range(1, n + 1):
        for combinacao in combinations(probabilidades, i):
            probabilidade_total = 1
            for prob in combinacao:
                probabilidade_total *= prob
            for prob in probabilidades:
                if prob not in combinacao:
                    probabilidade_total *= (1 - prob)
            melhor_probabilidade = max(melhor_probabilidade, probabilidade_total)

    return melhor_probabilidade

